1	import express, { type Request, Response, NextFunction } from "express";
2	import fs from "fs";
3	import path from "path";
4	import helmet from "helmet";
5	import compression from "compression";
6	import { spawnSync } from "child_process";
7	import { registerRoutes } from "./routes";
8	import { setupVite, serveStatic, log } from "./vite";
9	import { seedDatabase } from "./seed";
10	import { isDatabaseConnected, getDb } from "./database";
11	import { sql } from "drizzle-orm";
12	import { 
13	  startServerWithPortManagement, 
14	  setupGracefulShutdown, 
15	  getPortConflictHelp 
16	} from "./port-manager";
17	
18	const app = express();
19	
20	// ============================================
21	// SECURITY HEADERS - Payment Processor Grade
22	// ============================================
23	const isProduction = process.env.NODE_ENV === 'production';
24	
25	// Security headers - CSP enabled in production, disabled in dev for Replit webview compatibility
26	app.use(helmet({
27	  contentSecurityPolicy: isProduction ? {
28	    directives: {
29	      defaultSrc: ["'self'"],
30	      scriptSrc: ["'self'", "'unsafe-inline'", "https://pay.google.com", "https://applepay.cdn-apple.com", "https://uat.windcave.com", "https://sec.windcave.com"],
31	      styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
32	      fontSrc: ["'self'", "https://fonts.gstatic.com"],
33	      imgSrc: ["'self'", "data:", "blob:", "https:"],
34	      connectSrc: ["'self'", "https://uat.windcave.com", "https://sec.windcave.com", "https://pay.google.com"],
35	      frameSrc: ["'self'", "https://sec.windcave.com", "https://uat.windcave.com", "https://pay.google.com"],
36	      objectSrc: ["'none'"],
37	      baseUri: ["'self'"],
38	      formAction: ["'self'"],
39	      upgradeInsecureRequests: [],
40	    },
41	  } : false,
42	  frameguard: isProduction ? { action: 'deny' } : false,
43	  hidePoweredBy: true,
44	  hsts: isProduction ? {
45	    maxAge: 31536000,
46	    includeSubDomains: true,
47	    preload: true,
48	  } : false,
49	  noSniff: true,
50	  xssFilter: true,
51	  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
52	  dnsPrefetchControl: { allow: false },
53	  crossOriginOpenerPolicy: { policy: "same-origin-allow-popups" },
54	}));
55	
56	// Gzip compression for all responses — skips already-compressed assets and
57	// very small payloads (< 1 KB) where compression overhead outweighs savings.
58	app.use(compression({ threshold: 1024 }));
59	
60	// Skip JSON parsing for webhook routes to preserve raw body for signature verification
61	app.use((req, res, next) => {
62	  if (req.path === '/api/crypto-transactions/webhook/coinbase' || req.path === '/api/windcave/notification') {
63	    next();
64	  } else {
65	    express.json()(req, res, next);
66	  }
67	});
68	
69	app.use(express.urlencoded({ extended: false }));
70	
71	app.use((req, res, next) => {
72	  const start = Date.now();
73	  const path = req.path;
74	  let capturedJsonResponse: Record<string, any> | undefined = undefined;
75	
76	  const originalResJson = res.json;
77	  res.json = function (bodyJson, ...args) {
78	    capturedJsonResponse = bodyJson;
79	    return originalResJson.apply(res, [bodyJson, ...args]);
80	  };
81	
82	  res.on("finish", () => {
83	    const duration = Date.now() - start;
84	    if (path.startsWith("/api")) {
85	      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
86	      if (capturedJsonResponse) {
87	        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
88	      }
89	
90	      if (logLine.length > 80) {
91	        logLine = logLine.slice(0, 79) + "…";
92	      }
93	
94	      log(logLine);
95	    }
96	  });
97	
98	  next();
99	});
100	
101	(async () => {
102	  // ── JWT_SECRET validation ────────────────────────────────────────────────
103	  if (!process.env.JWT_SECRET) {
104	    if (isProduction) {
105	      console.error('');
106	      console.error('[FATAL] JWT_SECRET is NOT set in production.');
107	      console.error('  Set JWT_SECRET in your deployment secrets to a strong random value.');
108	      console.error('  Refusing to start — running without JWT_SECRET in production is insecure.');
109	      console.error('');
110	      process.exit(1);
111	    } else {
112	      console.warn('⚠️  JWT_SECRET not set — using development fallback (acceptable in dev only).');
113	      process.env.JWT_SECRET = 'dev-secret-key-change-in-production';
114	    }
115	  } else {
116	    console.log('✅ JWT_SECRET: configured');
117	  }
118	
119	  // ── Database connectivity verification ───────────────────────────────────
120	  // isDatabaseConnected() only checks that the Neon client was initialised.
121	  // Do a real query here to confirm the database is actually reachable before
122	  // accepting any traffic. Fail fast in production; warn only in development.
123	  if (isDatabaseConnected()) {
124	    try {
125	      const db = getDb();
126	      await db!.execute(sql`SELECT 1`);
127	      console.log('✅ Database: connection verified (live query succeeded)');
128	    } catch (error) {
129	      if (isProduction) {
130	        console.error('FATAL: Database is unreachable after connection was established:');
131	        console.error(error);
132	        console.error('Refusing to start — merchant data cannot be read or written.');
133	        process.exit(1);
134	      } else {
135	        console.warn('⚠️  Database live-query check failed (continuing in dev mode):', error);
136	      }
137	    }
138	  }
139	
140	  // ── Schema push (drizzle-kit push) ───────────────────────────────────────
141	  // Never run schema sync as a normal app-start side effect. The trades branch
142	  // must use reviewed additive SQL, and drizzle-kit push can propose destructive
143	  // live-DB changes. Opt in only for a deliberate, supervised run.
144	  //
145	  // DATA SAFETY: --force is intentionally omitted. Without --force, drizzle-kit
146	  // refuses to apply destructive changes (column drops, table drops) and returns
147	  // a non-zero exit code instead of silently destroying live data. If you need
148	  // to apply schema changes, run `npm run db:push` manually after reviewing
149	  // exactly what will be changed, or start with RUN_SCHEMA_PUSH=true.
150	  const runSchemaPush = process.env.RUN_SCHEMA_PUSH === 'true' || process.env.RUN_MIGRATIONS === 'true';
151	  if (isDatabaseConnected() && runSchemaPush) {
152	    log('Running schema push to sync database...');
153	    try {
154	      const drizzleConfigPath = path.resolve(process.cwd(), 'drizzle.config.ts');
155	      const configExists = fs.existsSync(drizzleConfigPath);
156	      if (configExists) {
157	        const push = spawnSync(
158	          'npx',
159	          ['drizzle-kit', 'push', `--config=${drizzleConfigPath}`],
160	          {
161	            stdio: 'pipe',
162	            encoding: 'utf8',
163	            timeout: 30_000,
164	            env: { ...process.env },
165	          }
166	        );
167	        if (push.status === 0) {
168	          log('✅ Schema: database schema is up to date');
169	        } else {
170	          const output = (push.stdout || '') + (push.stderr || '');
171	          // Non-zero exit most likely means a destructive change was blocked.
172	          // The server continues safely — no data was modified.
173	          log(`⚠️  Schema has destructive changes — run \`npm run db:push\` manually to review before applying. Data untouched. Details: ${output.slice(0, 200)}`);
174	        }
175	      } else {
176	        log('⚠️  drizzle.config.ts not found at project root — skipping schema push');
177	      }
178	    } catch (err) {
179	      log(`⚠️  Schema push threw an error (non-fatal): ${err}`);
180	    }
181	  }
182	
183	  const server = await registerRoutes(app);
184	
185	  // Initialize database with seed data if connected
186	  if (isDatabaseConnected()) {
187	    try {
188	      await seedDatabase();
189	    } catch (error) {
190	      log(`⚠️ Database seeding failed: ${error}`);
191	    }
192	  }
193	
194	  // Sync verified merchants to recreate auth users
195	  try {
196	    const { syncVerifiedMerchants } = await import("./auth");
197	    await syncVerifiedMerchants();
198	  } catch (error) {
199	    log(`⚠️ Failed to sync verified merchants: ${error}`);
200	  }
201	
202	  // Ensure info_pack_leads table exists (additive migration, safe to re-run)
203	  if (isDatabaseConnected()) {
204	    try {
205	      const { getDb } = await import("./database");
206	      const { sql } = await import("drizzle-orm");
207	      const pgDb = getDb();
208	      if (pgDb) {
209	        await pgDb.execute(sql`
210	          CREATE TABLE IF NOT EXISTS info_pack_leads (
211	            id serial PRIMARY KEY,
212	            name text NOT NULL,
213	            email text NOT NULL,
214	            created_at timestamp DEFAULT now()
215	          )
216	        `);
217	        log("✅ info_pack_leads table ready");
218	      }
219	    } catch (error) {
220	      log(`⚠️ Failed to ensure info_pack_leads table: ${error}`);
221	    }
222	  }
223	
224	  // Mark all pre-existing verified/active merchants as onboarding completed
225	  // so they aren't forced through the new onboarding flow
226	  if (isDatabaseConnected()) {
227	    try {
228	      const { db } = await import("./db");
229	      const { merchants } = await import("../shared/schema");
230	      const { eq, or } = await import("drizzle-orm");
231	      await db.update(merchants)
232	        .set({ onboardingCompleted: true })
233	        .where(
234	          or(
235	            eq(merchants.status, 'verified'),
236	            eq(merchants.status, 'active')
237	          )
238	        );
239	      log("✅ Existing verified merchants marked as onboarding completed");
240	    } catch (error) {
241	      log(`⚠️ Failed to mark existing merchants as onboarded: ${error}`);
242	    }
243	  }
244	
245	  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
246	    const status = err.status || err.statusCode || 500;
247	    const message = err.message || "Internal Server Error";
248	
249	    res.status(status).json({ message });
250	    throw err;
251	  });
252	
253	
254	  const CRAWLER_UA_PATTERN = /bot|crawl|spider|slurp|facebookexternalhit|linkedinbot|twitterbot|whatsapp|telegram|pinterest|googlebot|bingbot|yandex|baiduspider|duckduckbot|applebot|ia_archiver|semrush|ahrefs|mj12bot/i;
255	
